INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DisplayPort nur für Videoübertragung gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Überträgt auch Audio"}, {"text": "Ja", "correct": false, "because": "Audio wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Organisation hat DisplayPort standardisiert?', 3, '[{"text": "VESA", "correct": true, "because": "Video Electronics Standards Association"}, {"text": "IEEE", "correct": false, "because": "Andere Standards"}, {"text": "ISO", "correct": false, "because": "Nicht zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features unterstützt DisplayPort?', 5, '[{"text": "Hohe Auflösungen", "correct": true, "because": "Bis 8K"}, {"text": "Multi-Stream Transport", "correct": true, "because": "Mehrere Monitore"}, {"text": "Analoge Signale", "correct": false, "because": "Nur digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DisplayPort ist lizenzfrei. b) Es ersetzt HDMI komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HDMI bleibt relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DisplayPort?', 4, '[{"text": "Kabelversion", "correct": false, "because": "Beeinflusst Bandbreite"}, {"text": "Gerätekompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Monitorgröße", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DisplayPort auch USB-Daten überträgt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur mit Alt Mode über USB-C"}, {"text": "Ja", "correct": false, "because": "Standardmäßig nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Version brachte Multi-Stream Transport?', 3, '[{"text": "1.2", "correct": true, "because": "Eingeführt 2010"}, {"text": "1.4", "correct": false, "because": "Spätere Version"}, {"text": "2.0", "correct": false, "because": "Noch später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DisplayPort?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Bis 80 Gbps"}, {"text": "Mehrere Monitore", "correct": true, "because": "MST-Unterstützung"}, {"text": "Physische Größe", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DisplayPort unterstützt 8K. b) Es braucht immer Adapter für HDMI. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adapter optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DisplayPort?', 4, '[{"text": "Kompatibles Gerät", "correct": false, "because": "Notwendig"}, {"text": "Kabel", "correct": false, "because": "Übertragung"}, {"text": "Externes Netzteil", "correct": true, "because": "Strom über Gerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DisplayPort dasselbe wie HDMI?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Standards"}, {"text": "Ja", "correct": false, "because": "Verschiedene Technologien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte nutzen DisplayPort typischerweise?', 4, '[{"text": "PCs", "correct": true, "because": "Häufige Schnittstelle"}, {"text": "Monitore", "correct": true, "because": "Videoausgabe"}, {"text": "Drucker", "correct": false, "because": "Kein Display"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DisplayPort nur für Monitore ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Projektoren"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DisplayPort?', 3, '[{"text": "Bandbreite", "correct": true, "because": "Für hohe Auflösungen"}, {"text": "Kabeldesign", "correct": false, "because": "Sekundär"}, {"text": "Länge", "correct": false, "because": "Situativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DisplayPort nutzt Paketdaten. b) Es ist analog.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Digital, nicht analog"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Versionen gibt es von DisplayPort?', 5, '[{"text": "1.4", "correct": true, "because": "Aktuelle Version"}, {"text": "2.1", "correct": true, "because": "Neueste Version"}, {"text": "3.0", "correct": false, "because": "Noch nicht verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DisplayPort unwichtig?', 3, '[{"text": "Auflösungsunterstützung", "correct": false, "because": "Kernmerkmal"}, {"text": "Kompatibilität", "correct": false, "because": "Entscheidend"}, {"text": "Steckerfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt DisplayPort mehrere Monitore?', 3, '[{"text": "Ja", "correct": true, "because": "Via MST"}, {"text": "Nein", "correct": false, "because": "MST möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DisplayPort lizenzfrei ist?', 2, '[{"text": "Ja", "correct": true, "because": "Kein Lizenzgebühr"}, {"text": "Nein", "correct": false, "because": "VESA-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht DisplayPort besonders?', 4, '[{"text": "Paketübertragung", "correct": true, "because": "Wie Ethernet"}, {"text": "Analoge Signale", "correct": false, "because": "Nur digital"}, {"text": "Kurze Reichweite", "correct": false, "because": "Bis 15m"}]');
